import logging
import os

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn

logger = logging.getLogger(__name__)

try:  # AscendC extensions: hardware-accelerated row gather (GM -> UB).
    from triton.language.extra.cann import extension as _al
except Exception:  # pragma: no cover - older toolchains
    _al = None

_MAX_GRID_X = 65535  # device grid-dimension limit (Ascend coreDim <= 65535)
_INT32_MAX = 0x7FFFFFFF

# Device-side bounds assertion is only materialised when TRITON_DEBUG is set
# (`tl.device_assert` is a no-op otherwise).  Hoisting it behind a constexpr
# keeps the block-wide reduction that feeds it out of the production kernel.
_CHECK = os.environ.get("TRITON_DEBUG", "0") not in ("", "0", "false", "False")

# Bytes fetched per gathered element by the row-gather path.  A 32 B row maps
# to a single wide DMA transaction, which is markedly cheaper per element than
# a non-affine per-lane global load.
_ROW_BYTES = 32
# Largest source tensor that is still staged wholesale into the on-chip UB
# (196 KB) for a UB-side `tl.gather`.  Kept well below the hardware limit to
# leave room for the index/result tiles and double buffering.
_UB_SRC_BYTES = 64 * 1024

_FLOAT_DTYPES = (torch.float16, torch.bfloat16, torch.float32)


@triton.jit
def _narrow_idx(idx, n_in, WIDE: tl.constexpr):
    """Narrow a raw (int64) index to int32 and wrap negatives into [0, n_in).

    Ascend executes 64-bit vector integer ops several times slower than 32-bit
    ones, so the index is narrowed as early as possible.  ``n_in`` always fits
    in int32 on the paths that use it.
    """
    if not WIDE:
        idx = idx.to(tl.int32)
    # torch.take supports negative indices: wrap them into [0, n_in).
    return tl.where(idx < 0, idx + n_in, idx)


@triton.jit
def _clamp_idx(idx, n_in, WIDE: tl.constexpr):
    """Force ``idx`` into ``[0, n_in)``.

    Out-of-range indices are clamped (PyTorch raises instead); clamping keeps
    every address legal without paying for a predicated load, which would push
    the access onto a much slower non-affine path.
    """
    if WIDE:
        return tl.where((idx >= 0) & (idx < n_in), idx, 0)
    return tl.maximum(tl.minimum(idx, n_in - 1), 0)


@triton.jit
def _check_idx(idx, mask, n_in, BLOCK: tl.constexpr):
    # Reduce the check to a scalar: a per-lane ``device_assert`` costs the
    # whole kernel ~1.6x on Ascend.
    valid = (idx >= 0) & (idx < n_in)
    tl.device_assert(
        tl.sum((valid | (~mask)).to(tl.int32)) == BLOCK,
        "take(): index out of range",
    )


@triton.jit
def _take_ub_kernel(
    in_ptr,
    idx_ptr,
    out_ptr,
    n_index,
    n_in,
    NIN: tl.constexpr,
    SRC_MASKED: tl.constexpr,
    BLOCK: tl.constexpr,
    CHECK: tl.constexpr,
):
    """Whole (small) source staged in UB; the gather runs on-chip."""
    cols = tl.arange(0, NIN)
    if SRC_MASKED:
        src = tl.load(in_ptr + cols, mask=cols < n_in, other=0)
    else:
        src = tl.load(in_ptr + cols)

    pid = tl.program_id(axis=0)
    # Grid-stride loop: the launch grid is capped (see _MAX_GRID_X), so a
    # program may have to process several blocks for large ``n_index``.
    step = tl.num_programs(axis=0) * BLOCK
    block_start = pid * BLOCK
    while block_start < n_index:
        offs = block_start + tl.arange(0, BLOCK)
        mask = offs < n_index

        idx = _narrow_idx(tl.load(idx_ptr + offs, mask=mask, other=0), n_in, False)
        if CHECK:
            _check_idx(idx, mask, n_in, BLOCK)
        # Clamp out-of-range indices: the UB gather must stay inside ``src``.
        idx = _clamp_idx(idx, n_in, False)
        vals = tl.gather(src, idx, 0)
        tl.store(out_ptr + offs, vals, mask=mask)
        block_start += step


@triton.jit
def _take_rows_kernel(
    in_ptr,
    idx_ptr,
    out_ptr,
    n_index,
    n_in,
    NROWS: tl.constexpr,
    W: tl.constexpr,
    BLOCK: tl.constexpr,
    CHECK: tl.constexpr,
):
    """Gather 32 B rows (one DMA transaction per output element).

    ``input`` is viewed as ``(NROWS, W)``; each output element keeps lane
    ``idx % W`` of row ``idx // W``.  Reading a whole row turns the access into
    a single wide DMA, which is far cheaper per element than a non-affine
    per-lane global load.
    """
    lanes = tl.arange(0, W)[None, :]
    pid = tl.program_id(axis=0)
    step = tl.num_programs(axis=0) * BLOCK
    block_start = pid * BLOCK
    while block_start < n_index:
        offs = block_start + tl.arange(0, BLOCK)
        mask = offs < n_index

        idx = _narrow_idx(tl.load(idx_ptr + offs, mask=mask, other=0), n_in, False)
        if CHECK:
            _check_idx(idx, mask, n_in, BLOCK)
        idx = _clamp_idx(idx, n_in, False)

        rows = _al.index_select_simd(
            src=in_ptr,
            dim=0,
            index=idx // W,
            src_shape=[NROWS, W],
            src_offset=[-1, 0],
            read_shape=[-1, W],
        )
        sel = tl.sum(tl.where(lanes == (idx % W)[:, None], rows, 0), axis=1)
        tl.store(out_ptr + offs, sel.to(out_ptr.dtype.element_ty), mask=mask)
        block_start += step


@triton.jit
def _take_plain_kernel(
    in_ptr,
    idx_ptr,
    out_ptr,
    n_index,
    n_in,
    WIDE: tl.constexpr,
    BLOCK: tl.constexpr,
    CHECK: tl.constexpr,
):
    """Generic fallback: per-lane gather straight from global memory."""
    pid = tl.program_id(axis=0)
    step = tl.num_programs(axis=0) * BLOCK
    block_start = pid * BLOCK
    while block_start < n_index:
        offs = block_start + tl.arange(0, BLOCK)
        mask = offs < n_index

        idx = _narrow_idx(tl.load(idx_ptr + offs, mask=mask, other=0), n_in, WIDE)
        if CHECK:
            _check_idx(idx, mask, n_in, BLOCK)
        # Clamp the address rather than masking the load: an out-of-range index
        # never dereferences illegal memory, while folding ``valid`` into the
        # load mask pushes the access onto a much slower non-affine path.
        vals = tl.load(in_ptr + _clamp_idx(idx, n_in, WIDE), mask=mask, other=0)
        tl.store(out_ptr + offs, vals, mask=mask)
        block_start += step


def _launch_take(input, index, out_flat):
    input_flat = input.contiguous().view(-1)
    in_numel = input_flat.numel()
    n_index = index.numel()
    if n_index == 0:
        return
    # Feed the kernel native int64 indices; the 8 B/element index load is
    # cheap next to the gather itself.
    index_flat = index.contiguous().view(-1)
    with torch_device_fn.device(input.device):
        if input_flat.dtype in _FLOAT_DTYPES and in_numel <= _INT32_MAX:
            elem_bytes = input_flat.element_size()
            # `tl.gather` promotes bf16 sources to fp32 in UB, doubling the
            # footprint, so budget bf16 against a 4 B/element working set.
            ub_bytes = max(elem_bytes, 4)
            nin = triton.next_power_of_2(in_numel)
            if in_numel > 0 and nin * ub_bytes <= _UB_SRC_BYTES:
                block = min(max(triton.next_power_of_2(n_index), 128), 1024)
                grid = (min(triton.cdiv(n_index, block), _MAX_GRID_X),)
                _take_ub_kernel.run(
                    input_flat,
                    index_flat,
                    out_flat,
                    n_index,
                    in_numel,
                    NIN=nin,
                    SRC_MASKED=nin != in_numel,
                    BLOCK=block,
                    CHECK=_CHECK,
                    grid=grid,
                    warmup=False,
                )
                return
            w = _ROW_BYTES // elem_bytes
            if _al is not None and in_numel > 0 and in_numel % w == 0:
                block = 1024 if elem_bytes >= 4 else 512
                grid = (min(triton.cdiv(n_index, block), _MAX_GRID_X),)
                _take_rows_kernel.run(
                    input_flat,
                    index_flat,
                    out_flat,
                    n_index,
                    in_numel,
                    NROWS=in_numel // w,
                    W=w,
                    BLOCK=block,
                    CHECK=_CHECK,
                    grid=grid,
                    warmup=False,
                )
                return
        block = 1024
        grid = (min(triton.cdiv(n_index, block), _MAX_GRID_X),)
        _take_plain_kernel.run(
            input_flat,
            index_flat,
            out_flat,
            n_index,
            in_numel,
            WIDE=in_numel > _INT32_MAX,
            BLOCK=block,
            CHECK=_CHECK,
            grid=grid,
            warmup=False,
        )


def take(input, index):
    logger.debug("GEMS TAKE")
    if input.device != index.device:
        raise RuntimeError("input and index must be on the same device")
    out_flat = torch.empty(index.numel(), device=input.device, dtype=input.dtype)
    _launch_take(input, index, out_flat)
    return out_flat.view(index.shape)


def take_out(input, index, *, out):
    logger.debug("GEMS TAKE_OUT")
    if not (input.device == index.device == out.device):
        raise RuntimeError("input, index and out must be on the same device")
    if out.dtype != input.dtype:
        raise RuntimeError(f"out must have dtype {input.dtype}, but got {out.dtype}")
    if tuple(out.shape) != tuple(index.shape):
        out.resize_(index.shape)
    if out.is_contiguous():
        out_flat = out.view(-1)
        _launch_take(input, index, out_flat)
    else:
        tmp_flat = torch.empty(index.numel(), device=input.device, dtype=input.dtype)
        _launch_take(input, index, tmp_flat)
        out.copy_(tmp_flat.view(index.shape))
    return out
